import { ACHIEVEMENTS, HARDWARE_CATALOG, MODEL_CATALOG, MODEL_SKILLS, OBJECTIVES, PATENTS, TECH_NODES, UPGRADES } from '../data/defaultState.js';
import { BALANCE, featureUnlocked, nextFeatureUnlock, skillUnlocked, viewUnlocked } from '../config/balance.js';
import { ITEM_CATALOG, ITEM_SLOT_TYPES } from '../data/itemCatalog.js';
import { CONSUMABLES, GEM_CONVENIENCE, REWARD_CACHES, REWARDED_BOOSTS, STORE_PRODUCTS } from '../data/metaCatalog.js';
import { DeveloperDashboard } from '../dev/developer-dashboard.js';
import { activeModel, canBuyUpgrade, canDevelop, computePerSecond, cycleIntelligence, developmentCyclePreview, economySnapshot, effectiveHardwareCost, effectiveHardwareOutput, effectiveModelStat, isHardwareUnlocked, marketingCost, marketingPurchasePreview, modelAvailablePoints, modelImprovementCost, modelSkillEconomyPreview, objectiveProgress, optimizeGain, PATENT_SLOT_PRICES, patentCurrentBonus, patentResearchPerSecond, patentResearchRequired, patentUpgradeCost, trainingEtaSeconds, trainingRatePerSecond, trainingRequiredForState } from '../systems/GameSystem.js';
import { availableSlots, equipItem } from '../systems/InventorySystem.js';
import { missionsWithProgress } from '../systems/MissionSystem.js';
import { inferCompanyBuild, modelBuildSummary } from '../systems/ModifierSystem.js';
import { branchInvestment } from '../data/technologyCatalog.js';
import { activeReward } from '../systems/RewardQueue.js';
import { animateElement } from './animation.js';
