      achievements: () => `<section class="achievement-summary panel"><span><small>UNLOCKED</small><strong data-achievement-count></strong></span><span><small>PERMANENT BONUS</small><strong data-achievement-bonus></strong></span><span><small>DEVELOPMENT CYCLES</small><strong data-cycle-count></strong></span></section><div class="achievement-grid">${ACHIEVEMENTS.map((achievement) => `<article class="panel achievement-card" data-achievement="${achievement.id}"><small>PERMANENT +${(achievement.reward * 100).toFixed(2)}%</small><h3>${achievement.name}</h3><span>${this.#number(achievement.target)} ${achievement.metric}</span></article>`).join('')}</div>`,
